// src/index.ts
import express from "express";
import cors from "cors";
import * as data from "./data";

const app = express();
const PORT = process.env.PORT ? Number(process.env.PORT) : 4000;
const DEFAULT_DEV_ORIGIN = "http://localhost:3000";
let FRONTEND_ORIGIN = process.env.FRONTEND_ORIGIN;
if (!FRONTEND_ORIGIN) {
  if (process.env.NODE_ENV === "production") {
    throw new Error("FRONTEND_ORIGIN env var is required in production");
  }
  console.warn(`FRONTEND_ORIGIN not set, defaulting to ${DEFAULT_DEV_ORIGIN} for local dev`);
  FRONTEND_ORIGIN = DEFAULT_DEV_ORIGIN;
}

app.use(cors({ origin: FRONTEND_ORIGIN }));
app.use(express.json());

app.use((req, _res, next) => {
  if (process.env.NODE_ENV !== "production") {
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  }
  next();
});

app.get("/api/health", (_req, res) => res.json({ status: "ok" }));

app.get("/api/kpis", (_req, res) => res.json(data.dashboardKpis));

app.get("/api/raw-materials", (_req, res) => res.json(data.rawMaterials));
app.post("/api/raw-materials", (req, res) => {
  const item = { id: `rm-${data.rawMaterials.length + 1}`, ...req.body };
  data.rawMaterials.push(item);
  res.status(201).json(item);
});
app.get("/api/raw-materials/:id", (req, res) => {
  const item = data.rawMaterials.find((m) => m.id === req.params.id);
  if (!item) return res.status(404).json({ error: "Not found" });
  res.json(item);
});
app.post("/api/raw-materials/:id/receipts", (req, res) => {
  res.status(201).json({ received: true, rawMaterialId: req.params.id, ...req.body });
});

app.get("/api/packaging-materials", (_req, res) => res.json(data.packagingMaterials));
app.post("/api/packaging-materials/:id/restock", (req, res) => {
  res.status(201).json({ restocked: true, materialId: req.params.id, ...req.body });
});

app.get("/api/batches", (_req, res) => res.json(data.productionBatches));
app.get("/api/batches/:id", (req, res) => {
  const item = data.productionBatches.find((b) => b.id === req.params.id);
  if (!item) return res.status(404).json({ error: "Not found" });
  res.json(item);
});
app.post("/api/batches", (req, res) => {
  const item = { id: `batch-${data.productionBatches.length + 1}`, status: "in_progress", ...req.body };
  data.productionBatches.push(item);
  res.status(201).json(item);
});
app.post("/api/batches/:id/overhead", (req, res) => {
  res.status(200).json({ allocated: true, batchId: req.params.id, ...req.body });
});

app.get("/api/finished-cartons", (_req, res) => res.json(data.finishedCartons));
app.post("/api/finished-cartons/packing-run", (req, res) => {
  res.status(201).json({ packed: true, ...req.body });
});

app.get("/api/customers", (_req, res) => res.json(data.customers));
app.post("/api/customers", (req, res) => {
  const item = { id: `cust-${data.customers.length + 1}`, currentBalance: 0, ...req.body };
  data.customers.push(item);
  res.status(201).json(item);
});
app.get("/api/customers/:id", (req, res) => {
  const item = data.customers.find((c) => c.id === req.params.id);
  if (!item) return res.status(404).json({ error: "Not found" });
  res.json(item);
});
app.get("/api/customers/:id/item-prices", (req, res) => {
  const rows = data.customerItemPrices.filter((p) => p.customerId === req.params.id);
  res.json(rows);
});

app.get("/api/invoices", (_req, res) => res.json(data.invoices));
app.get("/api/invoices/:id", (req, res) => {
  const item = data.invoices.find((i) => i.id === req.params.id);
  if (!item) return res.status(404).json({ error: "Not found" });
  res.json(item);
});
app.post("/api/invoices", (req, res) => {
  const item = { id: `inv-${1000 + data.invoices.length + 1}`, status: "unpaid", ...req.body };
  data.invoices.push(item);
  res.status(201).json(item);
});
app.get("/api/invoices/:id/pdf", (req, res) => {
  res.status(200).json({ message: "PDF generation not implemented yet", invoiceId: req.params.id });
});

app.get("/api/payments", (_req, res) => res.json(data.payments));
app.post("/api/payments", (req, res) => {
  const item = { id: `pay-${data.payments.length + 1}`, ...req.body };
  data.payments.push(item);
  res.status(201).json(item);
});

app.get("/api/reports/inventory", (_req, res) => {
  res.json({ rawMaterials: data.rawMaterials, packagingMaterials: data.packagingMaterials });
});
app.get("/api/reports/pnl", (_req, res) => {
  res.json({ batches: data.productionBatches, invoices: data.invoices });
});

app.get("/api/settings", (_req, res) => res.json(data.settings));
app.patch("/api/settings", (req, res) => {
  Object.assign(data.settings, req.body);
  res.json(data.settings);
});

app.listen(PORT, () => {
  console.log(`GhaniFoods backend running on port ${PORT} (origin: ${FRONTEND_ORIGIN})`);
});

// Allocate overhead (electricity/gas/rent) onto a batch's cost/kg
// POST /functions/v1/batches-overhead
import { corsHeaders } from "../_shared/cors.ts";
import { getClient, statusForPgError, jsonResponse, envelopeError, envelopeSuccess } from "../_shared/client.ts";

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  try {
    const body = await req.json();
    const supabase = getClient(req);

    const rpcParams = {
    p_batch_id: body.batchId,
    p_electricity: body.electricity ?? 0,
    p_gas: body.gas ?? 0,
    p_rent: body.rent ?? 0,
    };

    const { data, error } = await supabase.rpc("fn_allocate_overhead", rpcParams);

    if (error) {
      const status = statusForPgError(error.message);
      return jsonResponse(envelopeError(error.message, error.code ?? "DB_ERROR"), status, corsHeaders);
    }

    return jsonResponse(envelopeSuccess(data), 201, corsHeaders);
  } catch (err) {
    return jsonResponse(envelopeError(err instanceof Error ? err.message : "Unknown error", "BAD_REQUEST"), 400, corsHeaders);
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

// Creates a Supabase client that forwards the caller's JWT, so RLS
// (authenticated-only policies) applies exactly as if the frontend
// called PostgREST directly. Never use the service role key here.
export function getClient(req: Request) {
  const authHeader = req.headers.get("Authorization") ?? "";
  return createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_ANON_KEY") ?? "",
    { global: { headers: { Authorization: authHeader } } }
  );
}

// Maps Postgres errcodes raised by fn_* functions to HTTP status codes
// per the response envelope convention in the backend spec.
export function statusForPgError(message: string): number {
  if (message.includes("insufficient")) return 409; // stock/balance conflicts
  if (message.includes("not found")) return 404;
  if (message.includes("required") || message.includes("must be")) return 400;
  return 500;
}

export function jsonResponse(body: unknown, status = 200, extraHeaders: Record<string, string> = {}) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json", ...extraHeaders },
  });
}

export function envelopeError(message: string, code = "ERROR", details: unknown = null) {
  return { data: null, error: { code, message, details } };
}

export function envelopeSuccess(data: unknown) {
  return { data, error: null };
}

export const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, PATCH, OPTIONS",
};

// Create a production batch (FR-20/21) with optional leftover carry-forward
// and optional named other-expenses (labour, packaging, misc, etc.)
// POST /functions/v1/batches
import { corsHeaders } from "../_shared/cors.ts";
import { getClient, statusForPgError, jsonResponse, envelopeError, envelopeSuccess } from "../_shared/client.ts";

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  try {
    const body = await req.json();
    const supabase = getClient(req);

    const rpcParams = {
    p_consumptions: body.consumptions,
    p_output_yield_kg: body.outputYieldKg,
    p_wastage_kg: body.wastageKg ?? 0,
    p_leftover_batch_id: body.leftoverBatchId ?? null,
    p_leftover_kg_used: body.leftoverKgUsed ?? null,
    p_other_expenses: body.otherExpenses ?? [],
    };

    const { data, error } = await supabase.rpc("fn_create_production_batch", rpcParams);

    if (error) {
      const status = statusForPgError(error.message);
      return jsonResponse(envelopeError(error.message, error.code ?? "DB_ERROR"), status, corsHeaders);
    }

    return jsonResponse(envelopeSuccess(data), 201, corsHeaders);
  } catch (err) {
    return jsonResponse(envelopeError(err instanceof Error ? err.message : "Unknown error", "BAD_REQUEST"), 400, corsHeaders);
  }
});

// Add a single named expense (labour, packaging, misc, etc.) to an
// EXISTING batch. For expenses added at batch-creation time, pass them
// via `otherExpenses` on POST /functions/v1/batches instead.
// POST /functions/v1/batch-expenses
// body: { batchId: string, name: string, amount: number }
import { corsHeaders } from "../_shared/cors.ts";
import { getClient, statusForPgError, jsonResponse, envelopeError, envelopeSuccess } from "../_shared/client.ts";

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  try {
    const body = await req.json();
    const supabase = getClient(req);

    const { data, error } = await supabase.rpc("fn_add_batch_expense", {
      p_batch_id: body.batchId,
      p_name: body.name,
      p_amount: body.amount ?? 0,
    });

    if (error) {
      const status = statusForPgError(error.message);
      return jsonResponse(envelopeError(error.message, error.code ?? "DB_ERROR"), status, corsHeaders);
    }

    return jsonResponse(envelopeSuccess(data), 201, corsHeaders);
  } catch (err) {
    return jsonResponse(envelopeError(err instanceof Error ? err.message : "Unknown error", "BAD_REQUEST"), 400, corsHeaders);
  }
});

// POST /functions/v1/boxes-create
import { corsHeaders } from "../_shared/cors.ts";
