// GET /functions/v1/dashboard-kpis
// Aggregates KPIs + low-stock alerts (FR-8) per backend spec section 2_dashboard.
import { corsHeaders } from "../_shared/cors.ts";
import { getClient, jsonResponse, envelopeError, envelopeSuccess } from "../_shared/client.ts";

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  try {
    const supabase = getClient(req);

    const [rawMaterials, wrappers, boxes, batches, finishedCartons, customers] = await Promise.all([
      supabase.from("raw_materials").select("id,name,quantity_in_stock,avg_unit_cost,low_stock_threshold"),
      supabase.from("wrappers").select("id,name,stock_qty,low_stock_threshold"),
      supabase.from("boxes").select("id,name,stock_qty,low_stock_threshold"),
      supabase.from("production_batches").select("id,batch_date"),
      supabase.from("finished_cartons").select("stock_qty"),
      supabase.from("customers").select("current_balance"),
    ]);

    for (const r of [rawMaterials, wrappers, boxes, batches, finishedCartons, customers]) {
      if (r.error) return jsonResponse(envelopeError(r.error.message, "DB_ERROR"), 500, corsHeaders);
    }

    const totalRawMaterialValue = (rawMaterials.data ?? []).reduce(
      (sum: number, m: Record<string, unknown>) => sum + Number(m.quantity_in_stock) * Number(m.avg_unit_cost), 0
    );

    const now = new Date();
    const batchesThisMonth = (batches.data ?? []).filter((b: Record<string, unknown>) => {
      const d = new Date(b.batch_date);
      return d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth();
    }).length;

    const finishedCartonsReady = (finishedCartons.data ?? []).reduce((s: number, c: Record<string, unknown>) => s + Number(c.stock_qty), 0);

    const totalReceivables = (customers.data ?? [])
      .filter((c: Record<string, unknown>) => Number(c.current_balance) > 0)
      .reduce((s: number, c: Record<string, unknown>) => s + Number(c.current_balance), 0);

    const lowStockAlerts = [
      ...(rawMaterials.data ?? [])
        .filter((m: Record<string, unknown>) => Number(m.quantity_in_stock) < Number(m.low_stock_threshold))
        .map((m: Record<string, unknown>) => ({ type: "rawMaterial", id: m.id, name: m.name, quantityInStock: Number(m.quantity_in_stock), threshold: Number(m.low_stock_threshold) })),
      ...(wrappers.data ?? [])
        .filter((w: Record<string, unknown>) => Number(w.stock_qty) < Number(w.low_stock_threshold))
        .map((w: Record<string, unknown>) => ({ type: "wrapper", id: w.id, name: w.name, quantityInStock: Number(w.stock_qty), threshold: Number(w.low_stock_threshold) })),
      ...(boxes.data ?? [])
        .filter((b: Record<string, unknown>) => Number(b.stock_qty) < Number(b.low_stock_threshold))
        .map((b: Record<string, unknown>) => ({ type: "box", id: b.id, name: b.name, quantityInStock: Number(b.stock_qty), threshold: Number(b.low_stock_threshold) })),
    ];

    return jsonResponse(envelopeSuccess({
      totalRawMaterialValue: Math.round(totalRawMaterialValue * 100) / 100,
      batchesThisMonth,
      finishedCartonsReady,
      totalReceivables: Math.round(totalReceivables * 100) / 100,
      lowStockAlerts,
    }), 200, corsHeaders);
  } catch (err) {
    return jsonResponse(envelopeError(err instanceof Error ? err.message : "Unknown error", "BAD_REQUEST"), 400, corsHeaders);
  }
});

// apps/backend/supabase/functions/data-delete/index.ts
//
// Deletes ALL business data (never auth/admin/user tables).
// Requires an exact confirmation phrase. Makes a full xlsx backup to
// storage before deleting, in case the user needs to recover.
//
// Request body: { confirmationText: string }
// Response: { deleted: Record<string, number>, backupUrl: string }

import { createClient } from "npm:@supabase/supabase-js@2";
import ExcelJS from "npm:exceljs@4";
import { corsHeaders } from "../_shared/cors.ts";

const CONFIRMATION_PHRASE = "DELETE ALL DATA";

// ---------------------------------------------------------------------
// IMPORTANT: adjust table names to match your real schema.
// Order matters: children (tables with foreign keys) must be listed
// BEFORE the parents they reference, so deletes don't violate FK constraints.
// This list intentionally excludes auth.users / any admin / profile tables.
// ---------------------------------------------------------------------
const DELETE_ORDER: string[] = [
  // -- deepest children first, verified against 0001_init_schema.sql --
  "payments",                   // FK -> customer_ledger_entries, customers
  "customer_ledger_entries",    // FK -> customers
  "customer_item_prices",       // FK -> customers, finished_cartons
  "invoice_items",               // FK -> invoices, finished_cartons
  "invoices",                    // FK -> customers
  "batch_consumptions",          // FK -> production_batches, raw_materials
  "finished_cartons",            // FK -> production_batches, carton_configurations
  "carton_configurations",       // FK -> wrappers, boxes
  "box_production_runs",         // FK -> boxes
  "wrapper_production_runs",     // FK -> wrappers
  "purchase_receipt_lines",      // FK -> purchase_receipts, raw_materials
  "purchase_receipts",           // FK -> suppliers
  "production_batches",          // self-referencing only
  "wrappers",                    // FK -> raw_materials
  "boxes",                       // FK -> raw_materials
  "raw_materials",
  "suppliers",
  "customers",
];

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, serviceKey);

    const body = await req.json();
    const { confirmationText } = body as { confirmationText: string };

    if (confirmationText !== CONFIRMATION_PHRASE) {
      return new Response(
        JSON.stringify({ error: `Confirmation text must exactly match "${CONFIRMATION_PHRASE}"` }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    // -----------------------------------------------------------------
    // 1. Backup everything to xlsx before deleting anything
    // -----------------------------------------------------------------
    const workbook = new ExcelJS.Workbook();
    workbook.creator = "GhaniFoods";
    workbook.created = new Date();

    const snapshots: Record<string, Record<string, unknown>[]> = {};

    for (const table of DELETE_ORDER) {
      const { data, error } = await supabase.from(table).select("*");
      if (error) throw new Error(`Backup fetch failed for ${table}: ${error.message}`);
      snapshots[table] = data ?? [];

      const sheet = workbook.addWorksheet(table.slice(0, 31));
      if (data && data.length > 0) {
        const headers = Object.keys(data[0]);
        sheet.addRow(headers).font = { bold: true };
        for (const row of data) sheet.addRow(headers.map((h) => (row as Record<string, unknown>)[h] ?? ""));
      } else {
        sheet.addRow(["(no data)"]);
      }
    }

    const buf = await workbook.xlsx.writeBuffer();
    const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
    const backupPath = `exports/GhaniFoods-pre-delete-backup-${timestamp}.xlsx`;

    const { error: uploadError } = await supabase.storage
      .from("exports")
      .upload(backupPath, new Uint8Array(buf as ArrayBuffer), {
        contentType: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        upsert: true,
      });
    if (uploadError) throw new Error(`Backup upload failed: ${uploadError.message}`);

    const { data: signed, error: signError } = await supabase.storage
      .from("exports")
      .createSignedUrl(backupPath, 3600); // 1 hour - give the user time to grab it
    if (signError) throw new Error(`Backup signed URL failed: ${signError.message}`);

    // -----------------------------------------------------------------
    // 2. Delete, in FK-safe order. Never touches auth/admin tables.
    // -----------------------------------------------------------------
    const deleted: Record<string, number> = {};

    for (const table of DELETE_ORDER) {
      const count = snapshots[table]?.length ?? 0;
      // Delete-all trick: match a condition that's always true for the primary key.
      // customer_item_prices has a COMPOSITE primary key (customer_id, item_id) -
      // it has no "id" column, so it needs a different always-true condition.
      const { error } =
        table === "customer_item_prices"
          ? await supabase.from(table).delete().not("customer_id", "is", null)
          : await supabase.from(table).delete().not("id", "is", null);
      if (error) throw new Error(`Delete failed for ${table}: ${error.message}`);
      deleted[table] = count;
    }

    return new Response(JSON.stringify({ deleted, backupUrl: signed.signedUrl }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (err) {
    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : "Delete failed" }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

// apps/backend/supabase/functions/data-export/index.ts
//
// Exports GhaniFoods business data as CSV, XLSX, PDF, or DOCX.
// Request body:
// {
//   modules: string[],              // keys from TABLE_MAP, or ["all"]
//   format: "csv" | "xlsx" | "pdf" | "docx",
//   dateRange?: { from?: string; to?: string }   // "YYYY-MM-DD", applied to date-bearing tables
// }
//
// Response: { downloadUrl: string, fileName: string }

import { createClient } from "npm:@supabase/supabase-js@2";
import ExcelJS from "npm:exceljs@4";
import { Document, Packer, Paragraph, HeadingLevel, Table, TableRow, TableCell, WidthType } from "npm:docx@9";
import { PDFDocument, StandardFonts, rgb } from "npm:pdf-lib@1";
import { corsHeaders } from "../_shared/cors.ts";

// ---------------------------------------------------------------------
// IMPORTANT: adjust these to match your real schema (see 0001_init_schema.sql)
// key = module name shown in the UI, value = { table, dateColumn? }
// ---------------------------------------------------------------------
const TABLE_MAP: Record<string, { table: string; dateColumn?: string }> = {
  rawMaterials: { table: "raw_materials" },
  suppliers: { table: "suppliers" },
  receipts: { table: "purchase_receipts", dateColumn: "purchase_date" },
  receiptLines: { table: "purchase_receipt_lines" },
  batches: { table: "production_batches", dateColumn: "created_at" },
  customers: { table: "customers" },
  invoices: { table: "invoices", dateColumn: "invoice_date" },
  invoiceLines: { table: "invoice_items" },
  payments: { table: "payments", dateColumn: "payment_date" },
  wrappers: { table: "wrappers" },
  boxes: { table: "boxes" },
  cartonConfigurations: { table: "carton_configurations" },
  finishedCartons: { table: "finished_cartons" },
};

const PROJECT_NAME = "GhaniFoods";

function humanize(key: string) {
  return key.replace(/([A-Z])/g, " $1").replace(/^./, (c) => c.toUpperCase());
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, serviceKey);

    const body = await req.json();
    let { modules, format, dateRange } = body as {
      modules: string[];
      format: "csv" | "xlsx" | "pdf" | "docx";
      dateRange?: { from?: string; to?: string };
    };

    if (!modules || modules.length === 0 || modules[0] === "all") {
      modules = Object.keys(TABLE_MAP);
    }
    modules = modules.filter((m) => TABLE_MAP[m]);

    if (modules.length === 0) {
      return new Response(JSON.stringify({ error: "No valid modules requested" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ---------------------------------------------------------------
    // 1. Fetch data for each module
    // ---------------------------------------------------------------
    const datasets: { key: string; label: string; rows: Record<string, unknown>[] }[] = [];

    for (const key of modules) {
      const { table, dateColumn } = TABLE_MAP[key];
      let query = supabase.from(table).select("*");

      if (dateColumn && dateRange?.from) query = query.gte(dateColumn, dateRange.from);
      if (dateColumn && dateRange?.to) query = query.lte(dateColumn, dateRange.to);

      const { data, error } = await query;
      if (error) throw new Error(`Failed to fetch ${table}: ${error.message}`);

      datasets.push({ key, label: humanize(key), rows: data ?? [] });
    }

    const generatedAt = new Date().toISOString();
    const rangeNote =
      dateRange?.from || dateRange?.to
        ? `Date range: ${dateRange?.from ?? "start"} to ${dateRange?.to ?? "today"}`
        : "Date range: all time";

    // ---------------------------------------------------------------
    // 2. Build the file
    // ---------------------------------------------------------------
    let fileBytes: Uint8Array;
    let ext: string;
    let contentType: string;

    if (format === "csv") {
      // If multiple modules, we zip-less concat with section headers (simplest, no extra dependency).
      const parts: string[] = [];
      for (const ds of datasets) {
        parts.push(`# ${ds.label}`);
        if (ds.rows.length === 0) {
          parts.push("(no data)");
        } else {
          const headers = Object.keys(ds.rows[0]);
          parts.push(headers.join(","));
          for (const row of ds.rows) {
            parts.push(
              headers
                .map((h) => {
                  const v = row[h];
                  const s = v === null || v === undefined ? "" : String(v);
                  return `"${s.replace(/"/g, '""')}"`;
                })
                .join(","),
            );
          }
        }
        parts.push("");
      }
      fileBytes = new TextEncoder().encode(parts.join("\n"));
      ext = "csv";
      contentType = "text/csv";
    } else if (format === "xlsx") {
      const workbook = new ExcelJS.Workbook();
      workbook.creator = PROJECT_NAME;
      workbook.created = new Date();

      for (const ds of datasets) {
        const sheet = workbook.addWorksheet(ds.label.slice(0, 31)); // Excel sheet name limit
        if (ds.rows.length > 0) {
          const headers = Object.keys(ds.rows[0]);
          sheet.addRow(headers).font = { bold: true };
          for (const row of ds.rows) sheet.addRow(headers.map((h) => row[h] ?? ""));
          sheet.columns.forEach((col) => (col.width = 18));
        } else {
          sheet.addRow(["(no data)"]);
        }
      }

      const buf = await workbook.xlsx.writeBuffer();
      fileBytes = new Uint8Array(buf as ArrayBuffer);
      ext = "xlsx";
      contentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
    } else if (format === "docx") {
      const children: Paragraph[] = [
        new Paragraph({ text: PROJECT_NAME, heading: HeadingLevel.TITLE }),
        new Paragraph({ text: "Data Export Report" }),
        new Paragraph({ text: `Generated: ${generatedAt}` }),
        new Paragraph({ text: rangeNote }),
        new Paragraph({ text: "" }),
      ];

      const content: (Paragraph | Table)[] = [...children];

      for (const ds of datasets) {
        content.push(new Paragraph({ text: ds.label, heading: HeadingLevel.HEADING_1 }));
        if (ds.rows.length === 0) {
          content.push(new Paragraph({ text: "(no data)" }));
          continue;
        }
        const headers = Object.keys(ds.rows[0]);
        const rows = [
          new TableRow({
            children: headers.map(
              (h) =>
                new TableCell({
                  width: { size: 100 / headers.length, type: WidthType.PERCENTAGE },
                  children: [new Paragraph({ text: h, heading: HeadingLevel.HEADING_5 })],
                }),
            ),
          }),
          ...ds.rows.map(
            (row) =>
              new TableRow({
                children: headers.map(
                  (h) =>
                    new TableCell({
                      width: { size: 100 / headers.length, type: WidthType.PERCENTAGE },
                      children: [new Paragraph({ text: String(row[h] ?? "") })],
                    }),
                ),
              }),
          ),
        ];
        content.push(new Table({ rows, width: { size: 100, type: WidthType.PERCENTAGE } }));
        content.push(new Paragraph({ text: "" }));
      }

      const doc = new Document({ sections: [{ children: content }] });
      const buf = await Packer.toBuffer(doc);
      fileBytes = new Uint8Array(buf);
      ext = "docx";
      contentType = "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
    } else if (format === "pdf") {
      const pdfDoc = await PDFDocument.create();
      const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
      const boldFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

      const pageWidth = 612;
      const pageHeight = 792;
      const margin = 40;
      const lineHeight = 14;

      let page = pdfDoc.addPage([pageWidth, pageHeight]);
      let y = pageHeight - margin;

      const ensureSpace = () => {
        if (y < margin + lineHeight) {
          page = pdfDoc.addPage([pageWidth, pageHeight]);
          y = pageHeight - margin;
        }
      };

      const drawText = (text: string, opts: { size?: number; bold?: boolean } = {}) => {
        ensureSpace();
        page.drawText(text, {
          x: margin,
          y,
          size: opts.size ?? 10,
          font: opts.bold ? boldFont : font,
          color: rgb(0, 0, 0),
        });
        y -= lineHeight;
      };

      drawText(PROJECT_NAME, { size: 20, bold: true });
      drawText("Data Export Report", { size: 12, bold: true });
      drawText(`Generated: ${generatedAt}`, { size: 9 });
      drawText(rangeNote, { size: 9 });
      y -= lineHeight;

      for (const ds of datasets) {
        drawText(ds.label, { size: 13, bold: true });
        if (ds.rows.length === 0) {
          drawText("(no data)", { size: 9 });
        } else {
          const headers = Object.keys(ds.rows[0]);
          drawText(headers.join(" | "), { size: 8, bold: true });
          for (const row of ds.rows) {
            const line = headers.map((h) => String(row[h] ?? "")).join(" | ");
            drawText(line.slice(0, 140), { size: 8 });
          }
        }
        y -= lineHeight / 2;
      }

      const buf = await pdfDoc.save();
      fileBytes = buf;
      ext = "pdf";
      contentType = "application/pdf";
    } else {
      return new Response(JSON.stringify({ error: "Unsupported format" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ---------------------------------------------------------------
    // 3. Upload to storage, return a signed URL
    // ---------------------------------------------------------------
    const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
    const fileName = `${PROJECT_NAME}-export-${timestamp}.${ext}`;
    const path = `exports/${fileName}`;

    const { error: uploadError } = await supabase.storage
      .from("exports")
      .upload(path, fileBytes, { contentType, upsert: true });
    if (uploadError) throw new Error(`Upload failed: ${uploadError.message}`);

    const { data: signed, error: signError } = await supabase.storage
      .from("exports")
      .createSignedUrl(path, 300); // 5 minutes
    if (signError) throw new Error(`Signed URL failed: ${signError.message}`);

    return new Response(JSON.stringify({ downloadUrl: signed.signedUrl, fileName }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (err) {
    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : "Export failed" }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

// GET /functions/v1/inventory-leftover-summary
// Total unconsumed bulk product (leftover_qty_kg) across all batches, plus per-batch breakdown.
import { corsHeaders } from "../_shared/cors.ts";
import { getClient, jsonResponse, envelopeError, envelopeSuccess } from "../_shared/client.ts";

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  try {
    const supabase = getClient(req);
    const { data, error } = await supabase
      .from("production_batches")
      .select("id, batch_date, leftover_qty_kg, bulk_cost_per_kg")
      .gt("leftover_qty_kg", 0)
      .order("batch_date", { ascending: false });

    if (error) return jsonResponse(envelopeError(error.message, "DB_ERROR"), 500, corsHeaders);

    const totalLeftoverKg = (data ?? []).reduce((s: number, b: Record<string, unknown>) => s + Number(b.leftover_qty_kg), 0);
    const totalLeftoverValue = (data ?? []).reduce(
      (s: number, b: Record<string, unknown>) => s + Number(b.leftover_qty_kg) * Number(b.bulk_cost_per_kg), 0
    );

    return jsonResponse(envelopeSuccess({
      totalLeftoverKg: Math.round(totalLeftoverKg * 1000) / 1000,
      totalLeftoverValue: Math.round(totalLeftoverValue * 100) / 100,
      byBatch: data,
    }), 200, corsHeaders);
  } catch (err) {
    return jsonResponse(envelopeError(err instanceof Error ? err.message : "Unknown error", "BAD_REQUEST"), 400, corsHeaders);
  }
});

// Create an invoice - deducts finished carton stock, updates customer ledger/balance
// POST /functions/v1/invoices
import { corsHeaders } from "../_shared/cors.ts";
import { getClient, statusForPgError, jsonResponse, envelopeError, envelopeSuccess } from "../_shared/client.ts";

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  try {
    const body = await req.json();
    const supabase = getClient(req);

    const rpcParams = {
    p_customer_id: body.customerId,
    p_lines: body.lines,
    };

    const { data, error } = await supabase.rpc("fn_create_invoice", rpcParams);

