"use client";

import { Fragment, useEffect, useMemo, useState } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { ChevronDown, ChevronRight, RefreshCw } from "lucide-react";
import { toast } from "@/components/ui/toast";
import { useStore } from "@/lib/store";
import { PurchaseReceiptDialog } from "@/components/ui/purchase-receipt-dialog";

export default function ReceiptsPage() {
  const receipts = useStore((s) => s.receipts);
  const receiptLines = useStore((s) => s.receiptLines);
  const suppliers = useStore((s) => s.suppliers);
  const rawMaterials = useStore((s) => s.rawMaterials);
  const loadRawMaterialsModule = useStore((s) => s.loadRawMaterialsModule);
  const deleteReceipt = useStore((s) => s.deleteReceipt);
  const updateReceipt = useStore((s) => s.updateReceipt);

  useEffect(() => {
    loadRawMaterialsModule();
  }, [loadRawMaterialsModule]);

  const [search, setSearch] = useState("");
  const [supplierFilter, setSupplierFilter] = useState("");
  const [materialFilter, setMaterialFilter] = useState("");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const handleRefresh = async () => {
    if (isRefreshing) return;
    setIsRefreshing(true);
    try {
      await loadRawMaterialsModule();
      toast.success("Table refreshed");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to refresh");
    } finally {
      setIsRefreshing(false);
    }
  };
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editRows, setEditRows] = useState<{ id: string; rawMaterialId: string; qty: string; cost: string }[]>([]);
  const [savingEdit, setSavingEdit] = useState(false);

  const rows = useMemo(() => {
    return receipts
      .map((r) => {
        const lines = receiptLines.filter((l) => l.receiptId === r.id);
        const supplier = suppliers.find((s) => s.id === r.supplierId);
        const totalValue = lines.reduce((sum, l) => sum + l.qty * l.cost, 0);
        const itemNames = lines.map((l) => rawMaterials.find((m) => m.id === l.rawMaterialId)?.name ?? "?");
        return { receipt: r, lines, supplier, totalValue, itemNames };
      })
      .filter(({ receipt, lines, supplier, itemNames }) => {
        if (supplierFilter && receipt.supplierId !== supplierFilter) return false;
        if (materialFilter && !lines.some((l) => l.rawMaterialId === materialFilter)) return false;
        if (fromDate && receipt.purchaseDate < fromDate) return false;
        if (toDate && receipt.purchaseDate > toDate) return false;
        if (search.trim()) {
          const q = search.trim().toLowerCase();
          const haystack = `${supplier?.name ?? ""} ${itemNames.join(" ")}`.toLowerCase();
          if (!haystack.includes(q)) return false;
        }
        return true;
      })
      .sort((a, b) => b.receipt.purchaseDate.localeCompare(a.receipt.purchaseDate));
  }, [receipts, receiptLines, suppliers, rawMaterials, supplierFilter, materialFilter, fromDate, toDate]);

  const hasFilters = !!(supplierFilter || materialFilter || fromDate || toDate);

  const startEdit = (receiptId: string, lines: { id: string; rawMaterialId: string; qty: number; cost: number }[]) => {
    setEditingId(receiptId);
    setExpandedId(receiptId);
    setEditRows(lines.map((l) => ({ id: l.id, rawMaterialId: l.rawMaterialId, qty: String(l.qty), cost: String(l.cost) })));
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditRows([]);
  };

  const saveEdit = async (receiptId: string, supplierId: string, purchaseDate: string) => {
    for (const row of editRows) {
      const qty = Number(row.qty);
      const cost = Number(row.cost);
      if (!qty || qty <= 0) { toast.error("Every line needs a quantity greater than 0"); return; }
      if (!cost || cost <= 0) { toast.error("Every line needs a cost greater than 0"); return; }
    }
    setSavingEdit(true);
    try {
      await updateReceipt(receiptId, {
        supplierId,
        purchaseDate,
        items: editRows.map((r) => ({ rawMaterialId: r.rawMaterialId, qty: Number(r.qty), cost: Number(r.cost) })),
      });
      toast.success("Receipt updated");
      setEditingId(null);
      setEditRows([]);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to update receipt");
    } finally {
      setSavingEdit(false);
    }
  };

  const handleDelete = async (receiptId: string) => {
    if (!window.confirm("Delete this receipt? This will reverse its effect on raw material stock. This cannot be undone.")) {
      return;
    }
    setDeletingId(receiptId);
    try {
      await deleteReceipt(receiptId);
      toast.success("Receipt deleted");
      if (expandedId === receiptId) setExpandedId(null);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to delete receipt");
    } finally {
      setDeletingId(null);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-2">
        <div className="flex items-center gap-2">
          <h1 className="text-xl font-semibold text-[var(--foreground)]">Receipts</h1>
          <button type="button" onClick={handleRefresh} disabled={isRefreshing} title="Refresh table" aria-label="Refresh table" className="shrink-0 rounded-lg border border-[var(--surface-border)] bg-[var(--surface)] p-2 text-[var(--text-muted)] hover:bg-[var(--surface-hover)] hover:text-[var(--foreground)] disabled:opacity-50 transition-colors">
            <RefreshCw className={`w-4 h-4 ${isRefreshing ? "animate-spin" : ""}`} />
          </button>
        </div>
        <button onClick={() => setDialogOpen(true)} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
          + Record Purchase
        </button>
      </div>

      <input
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        placeholder="Search receipts by supplier or raw material..."
        className="w-full max-w-sm rounded-lg border border-[var(--surface-border)] bg-[var(--surface)] px-3 py-2 text-sm text-[var(--foreground)] placeholder:text-[var(--text-faint)] outline-none focus:border-[var(--surface-border-strong)]"
      />

      <div className="flex flex-col sm:flex-row flex-wrap items-stretch sm:items-end gap-3 rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-4">
        <div>
          <label className="text-xs text-[var(--text-muted)]">Supplier</label>
          <select value={supplierFilter} onChange={(e) => setSupplierFilter(e.target.value)}
            className="mt-1 block rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
            <option value="">All suppliers</option>
            {suppliers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
          </select>
        </div>
        <div>
          <label className="text-xs text-[var(--text-muted)]">Raw Material</label>
          <select value={materialFilter} onChange={(e) => setMaterialFilter(e.target.value)}
            className="mt-1 block rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
            <option value="">All materials</option>
            {rawMaterials.map((m) => <option key={m.id} value={m.id}>{m.name}</option>)}
          </select>
        </div>
        <div>
          <label className="text-xs text-[var(--text-muted)]">From</label>
          <input value={fromDate} onChange={(e) => setFromDate(e.target.value)} type="date"
            className="mt-1 block rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
        </div>
        <div>
          <label className="text-xs text-[var(--text-muted)]">To</label>
          <input value={toDate} onChange={(e) => setToDate(e.target.value)} type="date"
            className="mt-1 block rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
        </div>
        {hasFilters && (
          <button
            type="button"
            onClick={() => { setSupplierFilter(""); setMaterialFilter(""); setFromDate(""); setToDate(""); }}
            className="rounded-lg px-3 py-2 text-xs text-[var(--text-muted)] hover:bg-[var(--surface-hover)]"
          >
            Clear filters
          </button>
        )}
      </div>

      <div className="overflow-x-auto rounded-xl border border-[var(--surface-border)]">
        <table className="w-full min-w-[720px] text-sm">
          <thead>
            <tr className="border-b border-[var(--surface-border)] bg-[var(--surface)] text-left text-[var(--text-muted)]">
              <th className="px-4 py-3 font-medium w-8"></th>
              <th className="px-4 py-3 font-medium">Receipt Date</th>
              <th className="px-4 py-3 font-medium">Supplier</th>
              <th className="px-4 py-3 font-medium">Items</th>
              <th className="px-4 py-3 font-medium">Total Value</th>
              <th className="px-4 py-3 font-medium text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {rows.length === 0 && (
              <tr><td colSpan={6} className="px-4 py-8 text-center text-[var(--text-faint)]">No receipts match these filters.</td></tr>
            )}
            {rows.map(({ receipt, lines, supplier, totalValue, itemNames }) => {
              const isExpanded = expandedId === receipt.id;
              const isEditing = editingId === receipt.id;
              const summary = itemNames.length > 2
                ? `${itemNames.length} items: ${itemNames.slice(0, 2).join(", ")}, +${itemNames.length - 2}`
                : `${itemNames.length} item${itemNames.length !== 1 ? "s" : ""}: ${itemNames.join(", ")}`;
              return (
                <Fragment key={receipt.id}>
                  <tr className="border-b border-[var(--surface-border)] last:border-0 hover:bg-[var(--surface)]/60">
                    <td className="px-4 py-3">
                      <button type="button" onClick={() => setExpandedId(isExpanded ? null : receipt.id)} className="text-[var(--text-muted)] hover:text-[var(--foreground)]">
                        {isExpanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                      </button>
                    </td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">{receipt.purchaseDate}</td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">
                      {supplier ? (
                        <NavLink href={`/suppliers/${supplier.id}`} className="hover:underline text-[var(--foreground)]">{supplier.name}</NavLink>
                      ) : "-"}
                    </td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">{summary}</td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">Rs. {totalValue.toLocaleString()}</td>
                    <td className="px-4 py-3 text-right">
                      <div className="flex justify-end gap-2">
                        <button
                          type="button"
                          onClick={() => (isEditing ? cancelEdit() : startEdit(receipt.id, lines))}
                          className="rounded-lg px-2.5 py-1 text-xs text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]"
                        >
                          {isEditing ? "Cancel" : "Edit"}
                        </button>
                        <button
                          type="button"
                          disabled={deletingId === receipt.id}
                          onClick={() => handleDelete(receipt.id)}
                          className="rounded-lg px-2.5 py-1 text-xs text-red-500 hover:bg-red-500/10 disabled:opacity-50"
                        >
                          {deletingId === receipt.id ? "Deleting..." : "Delete"}
                        </button>
                      </div>
                    </td>
                  </tr>
                  {isExpanded && (
                    <tr className="border-b border-[var(--surface-border)] last:border-0 bg-[var(--background)]">
                      <td></td>
                      <td colSpan={5} className="px-4 py-3">
                        <table className="w-full text-xs">
                          <thead>
                            <tr className="text-left text-[var(--text-muted)]">
                              <th className="pb-2 font-medium">Raw Material</th>
                              <th className="pb-2 font-medium">Quantity</th>
                              <th className="pb-2 font-medium">Cost/Unit</th>
                              <th className="pb-2 font-medium">Total</th>
                            </tr>
                          </thead>
                          <tbody>
                            {!isEditing && lines.map((l) => {
                              const material = rawMaterials.find((m) => m.id === l.rawMaterialId);
                              return (
                                <tr key={l.id} className="border-t border-[var(--surface-border)]">
                                  <td className="py-2 text-[var(--text-secondary)]">
                                    {material ? (
                                      <NavLink href={`/raw-materials/${material.id}`} className="hover:underline text-[var(--foreground)]">{material.name}</NavLink>
                                    ) : "-"}
                                  </td>
                                  <td className="py-2 text-[var(--text-secondary)]">{l.qty} {material?.unit ?? ""}</td>
                                  <td className="py-2 text-[var(--text-secondary)]">Rs. {l.cost.toLocaleString()}</td>
                                  <td className="py-2 text-[var(--text-secondary)]">Rs. {(l.qty * l.cost).toLocaleString()}</td>
                                </tr>
                              );
                            })}
                            {isEditing && editRows.map((row, idx) => {
                              const material = rawMaterials.find((m) => m.id === row.rawMaterialId);
                              return (
                                <tr key={row.id} className="border-t border-[var(--surface-border)]">
                                  <td className="py-2 text-[var(--text-secondary)]">{material?.name ?? "-"}</td>
                                  <td className="py-2">
                                    <input
                                      type="number"
                                      value={row.qty}
                                      onChange={(e) => setEditRows((rs) => rs.map((r, i) => (i === idx ? { ...r, qty: e.target.value } : r)))}
                                      className="w-20 rounded-md border border-[var(--surface-border)] bg-[var(--background)] px-2 py-1 text-xs text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]"
                                    /> <span className="text-[var(--text-faint)]">{material?.unit ?? ""}</span>
                                  </td>
                                  <td className="py-2">
                                    <input
                                      type="number"
                                      value={row.cost}
                                      onChange={(e) => setEditRows((rs) => rs.map((r, i) => (i === idx ? { ...r, cost: e.target.value } : r)))}
                                      className="w-24 rounded-md border border-[var(--surface-border)] bg-[var(--background)] px-2 py-1 text-xs text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]"
                                    />
                                  </td>
                                  <td className="py-2 text-[var(--text-secondary)]">
                                    Rs. {((Number(row.qty) || 0) * (Number(row.cost) || 0)).toLocaleString()}
                                  </td>
                                </tr>
                              );
                            })}
                          </tbody>
                        </table>
                        {isEditing && (
                          <div className="flex justify-end gap-2 pt-3">
                            <button type="button" onClick={cancelEdit} className="rounded-lg px-3 py-1.5 text-xs text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">
                              Cancel
                            </button>
                            <button
                              type="button"
                              disabled={savingEdit}
                              onClick={() => saveEdit(receipt.id, receipt.supplierId, receipt.purchaseDate)}
                              className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-3 py-1.5 text-xs font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 disabled:opacity-50"
                            >
                              {savingEdit ? "Saving..." : "Save changes"}
                            </button>
                          </div>
                        )}
                      </td>
                    </tr>
                  )}
                </Fragment>
              );
            })}
          </tbody>
        </table>
      </div>

      <PurchaseReceiptDialog open={dialogOpen} onClose={() => setDialogOpen(false)} />
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import {
  BarChart, Bar, LineChart, Line, XAxis, YAxis, CartesianGrid,
  Tooltip, ResponsiveContainer, Legend,
} from "recharts";
import { useStore } from "@/lib/store";
import { toast } from "@/components/ui/toast";
import { Skeleton } from "@/components/ui/skeleton";

function exportCSV(filename: string, headers: string[], rows: (string | number)[][]) {
  const lines = [headers.join(","), ...rows.map((r) => r.map((v) => `"${v}"`).join(","))];
  const blob = new Blob([lines.join("\n")], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
  toast.success(`${filename} downloaded`);
}

function SummaryCard({ label, value, tone = "default" }: { label: string; value: string | number; tone?: "default" | "positive" | "negative" }) {
  const valueColor =
    tone === "positive" ? "text-green-500" : tone === "negative" ? "text-red-500" : "text-[var(--foreground)]";
  return (
    <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-4">
      <div className="text-xs text-[var(--text-muted)]">{label}</div>
      <div className={`text-2xl font-semibold mt-1 ${valueColor}`}>{value}</div>
    </div>
  );
}

function EmptyChartState({ message }: { message: string }) {
  return (
    <div className="flex h-64 items-center justify-center rounded-lg border border-dashed border-[var(--surface-border)] text-sm text-[var(--text-faint)]">
      {message}
    </div>
  );
}

function ChartSkeleton() {
  return (
    <div className="space-y-3">
      <Skeleton className="h-64 w-full" />
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <Skeleton className="h-16 w-full" />
        <Skeleton className="h-16 w-full" />
      </div>
    </div>
  );
}

export default function ReportsPage() {
  const hydrated = useStore((s) => s.hydrated);
  const rawMaterials = useStore((s) => s.rawMaterials);
  const wrappers = useStore((s) => s.wrappers);
  const boxes = useStore((s) => s.boxes);
  const productionBatches = useStore((s) => s.productionBatches);
  const invoices = useStore((s) => s.invoices);
  const finishedCartons = useStore((s) => s.finishedCartons);

  const [tab, setTab] = useState<"inventory" | "yield" | "pnl">("inventory");
  const [from, setFrom] = useState("2026-08-01");
  const [to, setTo] = useState("2026-08-18");

  const inventoryData = useMemo(() => [
    ...rawMaterials.map((m) => ({ name: m.name, stock: m.quantityInStock, threshold: m.lowStockThreshold, type: "Raw" })),
    ...wrappers.map((w) => ({ name: w.name, stock: w.stockQty, threshold: w.lowStockThreshold, type: "Wrapper" })),
    ...boxes.map((b) => ({ name: b.name, stock: b.stockQty, threshold: b.lowStockThreshold, type: "Box" })),
  ], [rawMaterials, wrappers, boxes]);

  const lowStockCount = useMemo(
    () => inventoryData.filter((i) => i.stock < i.threshold).length,
    [inventoryData]
  );

  const yieldData = useMemo(() =>
    productionBatches.map((b) => ({
      batch: b.id,
      outputYield: b.outputYieldKg,
      wastage: b.wastageKg,
      leftover: b.leftoverQtyKg,
    })), [productionBatches]);

  const yieldTotals = useMemo(() => {
    const totalOutput = yieldData.reduce((s, b) => s + b.outputYield, 0);
    const totalWastage = yieldData.reduce((s, b) => s + b.wastage, 0);
    return { totalOutput, totalWastage };
  }, [yieldData]);

  const pnl = useMemo(() => {
    const filteredInvoices = invoices.filter((i) => i.invoiceDate >= from && i.invoiceDate <= to);
    const filteredBatches = productionBatches.filter((b) => b.batchDate >= from && b.batchDate <= to);
    const totalRevenue = filteredInvoices.reduce((sum, i) => sum + i.totalAmount, 0);
    const totalCost = filteredBatches.reduce((sum, b) => sum + b.outputYieldKg * b.bulkCostPerKg, 0);
    const grossProfit = totalRevenue - totalCost;

    const lineData = filteredInvoices
      .slice()
      .sort((a, b) => a.invoiceDate.localeCompare(b.invoiceDate))
      .map((inv) => ({ date: inv.invoiceDate, revenue: inv.totalAmount }));

    return { totalRevenue, totalCost, grossProfit, lineData };
  }, [invoices, productionBatches, from, to]);

  const cartonsReady = finishedCartons.reduce((sum, c) => sum + c.stockQty, 0);
  const cartonsValue = finishedCartons.reduce((sum, c) => sum + c.stockQty * c.costPerCarton, 0);

  const handleInventoryExport = () => {
    exportCSV("inventory.csv",
      ["Name", "Type", "Stock", "Threshold"],
      inventoryData.map((r) => [r.name, r.type, r.stock, r.threshold])
    );
  };
  const handleYieldExport = () => {
    exportCSV("production-yield.csv",
      ["Batch", "Output Yield (kg)", "Wastage (kg)", "Leftover (kg)"],
      yieldData.map((r) => [r.batch, r.outputYield, r.wastage, r.leftover])
    );
  };
  const handlePnlExport = () => {
    exportCSV("pnl.csv",
      ["Date", "Revenue"],
      pnl.lineData.map((r) => [r.date, r.revenue])
    );
  };

  // Theme-aware chart styling - reads the app's existing CSS variables
  // instead of hardcoded dark-mode-only hex values, so tooltips/axes
  // match whichever theme (light or dark) is currently active.
  const tooltipStyle = {
    backgroundColor: "var(--surface)",
    border: "1px solid var(--surface-border)",
    color: "var(--foreground)",
    borderRadius: 8,
  };
  const axisTickStyle = { fill: "var(--text-muted)", fontSize: 11 };
  const gridStroke = "var(--surface-border)";
  const legendStyle = { color: "var(--text-muted)", paddingTop: 16 };

  // Minimum pixel width per bar/category so labels stay legible when
  // there are many raw materials / wrappers / boxes / batches, instead
  // of squeezing everything into a fixed-width chart. The surrounding
  // container scrolls horizontally if this exceeds the viewport.
  const inventoryChartWidth = Math.max(inventoryData.length * 90, 600);
  const yieldChartWidth = Math.max(yieldData.length * 90, 600);

  if (!hydrated) {
    return (
      <div className="space-y-6">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">Reports and Analytics</h1>
        <ChartSkeleton />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <h1 className="text-xl font-semibold text-[var(--foreground)]">Reports and Analytics</h1>

      <div className="flex flex-col sm:flex-row flex-wrap items-stretch sm:items-end gap-3 rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-4">
        <div>
          <label className="text-xs text-[var(--text-muted)]">From</label>
          <input value={from} onChange={(e) => setFrom(e.target.value)} type="date"
            className="mt-1 block rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
        </div>
        <div>
          <label className="text-xs text-[var(--text-muted)]">To</label>
          <input value={to} onChange={(e) => setTo(e.target.value)} type="date"
            className="mt-1 block rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
        </div>
      </div>

      <div className="flex gap-2 border-b border-[var(--surface-border)]">
        {(["inventory", "yield", "pnl"] as const).map((key) => (
          <button key={key} onClick={() => setTab(key)}
            className={`px-4 py-2 text-sm font-medium border-b-2 capitalize transition-colors ${
              tab === key
                ? "border-[var(--foreground)] text-[var(--foreground)]"
                : "border-transparent text-[var(--text-muted)] hover:text-[var(--text-secondary)]"
            }`}>
            {key === "yield" ? "Production Yield" : key === "pnl" ? "P and L" : "Inventory Movement"}
          </button>
        ))}
      </div>

      {tab === "inventory" && (
        <div className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <SummaryCard label="Total Tracked Items" value={inventoryData.length} />
            <SummaryCard
              label="Items Low on Stock"
              value={lowStockCount}
              tone={lowStockCount > 0 ? "negative" : "positive"}
            />
          </div>

          <div className="flex justify-end">
            <button onClick={handleInventoryExport}
              className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)]">
              Export CSV
            </button>
          </div>

          <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5">
            <h2 className="text-sm font-semibold text-[var(--foreground)] mb-4">Stock vs Threshold</h2>
            {inventoryData.length === 0 ? (
              <EmptyChartState message="No raw materials, wrappers, or boxes tracked yet." />
            ) : (
              <div className="overflow-x-auto">
                <div style={{ width: inventoryChartWidth, minWidth: "100%" }}>
                  <ResponsiveContainer width="100%" height={320}>
                    <BarChart data={inventoryData} margin={{ top: 5, right: 20, left: 0, bottom: 60 }}>
                      <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                      <XAxis dataKey="name" tick={axisTickStyle} angle={-30} textAnchor="end" interval={0} />
                      <YAxis tick={axisTickStyle} />
                      <Tooltip contentStyle={tooltipStyle} />
                      <Legend wrapperStyle={legendStyle} />
                      <Bar dataKey="stock" name="Stock" fill="#3b82f6" radius={[4, 4, 0, 0]} />
                      <Bar dataKey="threshold" name="Threshold" fill="#ef4444" radius={[4, 4, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <SummaryCard label="Finished Cartons Ready" value={cartonsReady} />
            <SummaryCard
              label="Finished Stock Value (at cost)"
              value={`Rs. ${cartonsValue.toLocaleString(undefined, { maximumFractionDigits: 0 })}`}
            />
          </div>
        </div>
      )}

      {tab === "yield" && (
        <div className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <SummaryCard label="Total Output (kg)" value={yieldTotals.totalOutput.toLocaleString()} />
            <SummaryCard
              label="Total Wastage (kg)"
              value={yieldTotals.totalWastage.toLocaleString()}
              tone={yieldTotals.totalWastage > 0 ? "negative" : "positive"}
            />
          </div>

          <div className="flex justify-end">
            <button onClick={handleYieldExport}
              className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)]">
              Export CSV
            </button>
          </div>

          <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5">
            <h2 className="text-sm font-semibold text-[var(--foreground)] mb-4">Output Yield, Wastage and Leftover per Batch</h2>
            {yieldData.length === 0 ? (
              <EmptyChartState message="No production batches recorded yet." />
            ) : (
              <div className="overflow-x-auto">
                <div style={{ width: yieldChartWidth, minWidth: "100%" }}>
                  <ResponsiveContainer width="100%" height={320}>
                    <BarChart data={yieldData} margin={{ top: 5, right: 20, left: 0, bottom: 20 }}>
                      <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                      <XAxis dataKey="batch" tick={axisTickStyle} />
                      <YAxis tick={axisTickStyle} />
                      <Tooltip contentStyle={tooltipStyle} />
                      <Legend wrapperStyle={{ ...legendStyle, paddingTop: 8 }} />
                      <Bar dataKey="outputYield" name="Output (kg)" fill="#22c55e" radius={[4, 4, 0, 0]} />
                      <Bar dataKey="wastage" name="Wastage (kg)" fill="#ef4444" radius={[4, 4, 0, 0]} />
                      <Bar dataKey="leftover" name="Leftover (kg)" fill="#f59e0b" radius={[4, 4, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {tab === "pnl" && (
        <div className="space-y-4">
          <div className="flex justify-end">
            <button onClick={handlePnlExport}
              className="rounded-lg border border-neutral-400 dark:border-neutral-600 px-4 py-2 text-sm text-[var(--foreground)] hover:bg-[var(--surface-hover)]">
              Export CSV
            </button>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <SummaryCard label="Total Revenue" value={`Rs. ${pnl.totalRevenue.toLocaleString()}`} />
            <SummaryCard
              label="Est. Production Cost"
              value={`Rs. ${pnl.totalCost.toLocaleString(undefined, { maximumFractionDigits: 0 })}`}
            />
            <SummaryCard
              label="Est. Gross Profit"
              value={`Rs. ${pnl.grossProfit.toLocaleString(undefined, { maximumFractionDigits: 0 })}`}
              tone={pnl.grossProfit >= 0 ? "positive" : "negative"}
            />
          </div>

          <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5">
            <h2 className="text-sm font-semibold text-[var(--foreground)] mb-4">Revenue Over Time (selected period)</h2>
            {pnl.lineData.length === 0 ? (
              <EmptyChartState message="No invoices in the selected date range." />
            ) : (
              <ResponsiveContainer width="100%" height={280}>
                <LineChart data={pnl.lineData} margin={{ top: 5, right: 20, left: 0, bottom: 5 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} />
                  <XAxis dataKey="date" tick={axisTickStyle} />
                  <YAxis tick={axisTickStyle} />
                  <Tooltip contentStyle={tooltipStyle} />
                  <Line type="monotone" dataKey="revenue" name="Revenue (Rs.)" stroke="#3b82f6" strokeWidth={2} dot={{ fill: "#3b82f6", r: 4 }} />
                </LineChart>
              </ResponsiveContainer>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useRouter, useSearchParams } from "next/navigation";
import { toast } from "@/components/ui/toast";
import { useStore } from "@/lib/store";
import { ExportDataPanel } from "@/components/ui/export-data-panel";
import { DangerZonePanel } from "@/components/ui/danger-zone-panel";

const settingsSchema = z.object({
  businessName: z.string().trim().min(2, "Business name required"),
  address: z.string().trim().min(5, "Address required"),
  invoiceFooterText: z.string().trim(),
  defaultProfitMarginPercent: z.coerce.number().min(0, "Cannot be negative"),
  lowStockThresholdDefault: z.coerce.number().min(0, "Cannot be negative"),
  overheadAllocationMethod: z.enum(["equal", "proportional_kg"]),
});
type SettingsFormValues = z.infer<typeof settingsSchema>;

export default function SettingsPage() {
  const settings = useStore((s) => s.settings);
  const updateSettings = useStore((s) => s.updateSettings);
  const router = useRouter();
  const searchParams = useSearchParams();

  // ?tab=profile (default) | export
  const activeTab = searchParams.get("tab") === "export" ? "export" : "profile";

  const goToTab = (tab: "profile" | "export") => {
    router.push(`/settings?tab=${tab}`);
  };

  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<SettingsFormValues>({
    resolver: zodResolver(settingsSchema),
    defaultValues: settings,
  });

  const onSubmit = async (values: SettingsFormValues) => {
    try {
      await updateSettings(values);
      toast.success("Settings saved");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to save settings");
    }
  };

  return (
    <div className="max-w-2xl space-y-6">
      <h1 className="text-xl font-semibold text-[var(--foreground)]">Settings</h1>

      {/* Local tab strip - kept in addition to the left sidebar, so the page
          works correctly even if the sidebar link/query param changes later. */}
      <div className="flex gap-2 border-b border-[var(--surface-border)]">
        <button
          type="button"
          onClick={() => goToTab("profile")}
          className={`px-3 py-2 text-sm font-medium border-b-2 -mb-px transition-colors ${
            activeTab === "profile"
              ? "border-[var(--foreground)] text-[var(--foreground)]"
              : "border-transparent text-[var(--text-muted)] hover:text-[var(--text-secondary)]"
          }`}
        >
          Business Profile
        </button>
        <button
          type="button"
          onClick={() => goToTab("export")}
          className={`px-3 py-2 text-sm font-medium border-b-2 -mb-px transition-colors ${
            activeTab === "export"
              ? "border-[var(--foreground)] text-[var(--foreground)]"
              : "border-transparent text-[var(--text-muted)] hover:text-[var(--text-secondary)]"
          }`}
        >
          Export & Data
        </button>
      </div>

      {activeTab === "profile" && (
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
          <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4">
            <h2 className="text-sm font-semibold text-[var(--foreground)]">Business Profile</h2>

            <div>
              <label className="text-sm text-[var(--text-muted)]">Business Name</label>
              <input {...register("businessName")}
                className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
              {errors.businessName && <p className="text-xs text-red-400 mt-1">{errors.businessName.message}</p>}
            </div>

            <div>
              <label className="text-sm text-[var(--text-muted)]">Address</label>
              <input {...register("address")}
                className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
              {errors.address && <p className="text-xs text-red-400 mt-1">{errors.address.message}</p>}
            </div>

            <div>
              <label className="text-sm text-[var(--text-muted)]">Invoice Footer Text</label>
              <input {...register("invoiceFooterText")}
                className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            </div>
          </div>

          <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4">
            <h2 className="text-sm font-semibold text-[var(--foreground)]">Defaults</h2>

            <div>
              <label className="text-sm text-[var(--text-muted)]">Default Profit Margin %</label>
              <input {...register("defaultProfitMarginPercent")} type="number" step="any"
                className="mt-1 w-48 rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
              {errors.defaultProfitMarginPercent && <p className="text-xs text-red-400 mt-1">{errors.defaultProfitMarginPercent.message}</p>}
            </div>

            <div>
              <label className="text-sm text-[var(--text-muted)]">Low-Stock Threshold Default</label>
              <input {...register("lowStockThresholdDefault")} type="number"
                className="mt-1 w-48 rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
              {errors.lowStockThresholdDefault && <p className="text-xs text-red-400 mt-1">{errors.lowStockThresholdDefault.message}</p>}
            </div>

            <div>
              <label className="text-sm text-[var(--text-muted)]">Monthly Overhead Allocation Method</label>
              <select {...register("overheadAllocationMethod")}
                className="mt-1 w-full sm:w-64 rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]">
                <option value="equal">Equal split across batches</option>
                <option value="proportional_kg">Proportional to output (kg)</option>
              </select>
              <p className="text-xs text-[var(--text-faint)] mt-1">
                Default method pre-selected on the Monthly Expenses page when splitting electricity/gas/rent across batches.
              </p>
            </div>
          </div>

          <button
            type="submit"
            disabled={isSubmitting}
            className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-50 dark:text-neutral-950 hover:bg-neutral-200 disabled:opacity-50"
          >
            {isSubmitting ? "Saving..." : "Save Settings"}
          </button>
        </form>
      )}

      {activeTab === "export" && (
        <div className="space-y-6">
          <ExportDataPanel />
          <DangerZonePanel />
        </div>
      )}
    </div>
  );
}

"use client";

import { Fragment, use, useEffect, useMemo, useState } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { ChevronDown, ChevronRight } from "lucide-react";
import { useStore } from "@/lib/store";
import { PurchaseReceiptDialog } from "@/components/ui/purchase-receipt-dialog";

export default function SupplierDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const supplier = useStore((s) => s.suppliers.find((sup) => sup.id === id));
  const allReceipts = useStore((s) => s.receipts);
  const receiptLines = useStore((s) => s.receiptLines);
  const rawMaterials = useStore((s) => s.rawMaterials);
  const loadRawMaterialsModule = useStore((s) => s.loadRawMaterialsModule);
  const [expandedReceiptId, setExpandedReceiptId] = useState<string | null>(null);
  const [dialogOpen, setDialogOpen] = useState(false);

  useEffect(() => {
    loadRawMaterialsModule();
  }, [loadRawMaterialsModule]);

  const receipts = useMemo(
    () => allReceipts.filter((r) => r.supplierId === id).sort((a, b) => b.purchaseDate.localeCompare(a.purchaseDate)),
    [allReceipts, id]
  );

  const receiptSummaries = useMemo(() => {
    return receipts.map((r) => {
      const lines = receiptLines.filter((l) => l.receiptId === r.id);
      const totalValue = lines.reduce((sum, l) => sum + l.qty * l.cost, 0);
      return { receipt: r, lines, itemCount: lines.length, totalValue };
    });
  }, [receipts, receiptLines]);

  const totalLifetimeValue = useMemo(
    () => receiptSummaries.reduce((sum, r) => sum + r.totalValue, 0),
    [receiptSummaries]
  );

  if (!supplier) {
    return (
      <div className="space-y-4">
        <NavLink href="/suppliers" className="text-sm text-[var(--text-muted)] hover:underline">&larr; Back to Suppliers</NavLink>
        <p className="text-[var(--text-muted)]">Supplier not found.</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="text-sm text-[var(--text-muted)]">
        <NavLink href="/suppliers" className="hover:underline text-[var(--text-secondary)]">Suppliers</NavLink>{" "}
        / <span className="text-[var(--foreground)]">{supplier.name}</span>
      </div>

      <div className="rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">{supplier.name}</h1>
        <p className="text-sm text-[var(--text-muted)] mt-1">{supplier.phone}</p>
        {supplier.address && <p className="text-sm text-[var(--text-muted)]">{supplier.address}</p>}

        <div className="mt-5 grid grid-cols-2 sm:grid-cols-3 gap-4">
          <div>
            <div className="text-[var(--text-muted)] text-xs">Total Receipts</div>
            <div className="text-lg font-semibold text-[var(--foreground)] mt-1">{receipts.length}</div>
          </div>
          <div>
            <div className="text-[var(--text-muted)] text-xs">Total Lifetime Value</div>
            <div className="text-lg font-semibold text-[var(--foreground)] mt-1">Rs. {totalLifetimeValue.toLocaleString()}</div>
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">Purchase History</h2>
        <button onClick={() => setDialogOpen(true)} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
          + Record Purchase
        </button>
      </div>

      <div className="overflow-x-auto rounded-xl border border-[var(--surface-border)]">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-[var(--surface-border)] bg-[var(--surface)] text-left text-[var(--text-muted)]">
              <th className="px-4 py-3 font-medium w-8"></th>
              <th className="px-4 py-3 font-medium">Receipt Date</th>
              <th className="px-4 py-3 font-medium">Items</th>
              <th className="px-4 py-3 font-medium">Total Value</th>
            </tr>
          </thead>
          <tbody>
            {receiptSummaries.map(({ receipt, lines, itemCount, totalValue }) => {
              const isExpanded = expandedReceiptId === receipt.id;
              return (
                <Fragment key={receipt.id}>
                  <tr className="border-b border-[var(--surface-border)] last:border-0 hover:bg-[var(--surface)]/60">
                    <td className="px-4 py-3">
                      <button
                        type="button"
                        onClick={() => setExpandedReceiptId(isExpanded ? null : receipt.id)}
                        className="text-[var(--text-muted)] hover:text-[var(--foreground)]"
                      >
                        {isExpanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                      </button>
                    </td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">{receipt.purchaseDate}</td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">{itemCount} item{itemCount !== 1 ? "s" : ""}</td>
                    <td className="px-4 py-3 text-[var(--text-secondary)]">Rs. {totalValue.toLocaleString()}</td>
                  </tr>
                  {isExpanded && (
                    <tr className="border-b border-[var(--surface-border)] last:border-0 bg-[var(--background)]">
                      <td></td>
                      <td colSpan={3} className="px-4 py-3">
                        <table className="w-full text-xs">
                          <thead>
                            <tr className="text-left text-[var(--text-muted)]">
                              <th className="pb-2 font-medium">Raw Material</th>
                              <th className="pb-2 font-medium">Quantity</th>
                              <th className="pb-2 font-medium">Cost/Unit</th>
                              <th className="pb-2 font-medium">Total</th>
                            </tr>
                          </thead>
                          <tbody>
                            {lines.map((l) => {
                              const material = rawMaterials.find((m) => m.id === l.rawMaterialId);
                              return (
                                <tr key={l.id} className="border-t border-[var(--surface-border)]">
                                  <td className="py-2 text-[var(--text-secondary)]">
                                    {material ? (
                                      <NavLink href={`/raw-materials/${material.id}`} className="hover:underline text-[var(--foreground)]">{material.name}</NavLink>
                                    ) : "-"}
                                  </td>
                                  <td className="py-2 text-[var(--text-secondary)]">{l.qty} {material?.unit ?? ""}</td>
                                  <td className="py-2 text-[var(--text-secondary)]">Rs. {l.cost.toLocaleString()}</td>
                                  <td className="py-2 text-[var(--text-secondary)]">Rs. {(l.qty * l.cost).toLocaleString()}</td>
                                </tr>
                              );
                            })}
                          </tbody>
                        </table>
                      </td>
                    </tr>
                  )}
                </Fragment>
              );
            })}
            {receiptSummaries.length === 0 && (
              <tr><td colSpan={4} className="px-4 py-8 text-center text-[var(--text-faint)]">No purchases recorded yet for this supplier.</td></tr>
            )}
          </tbody>
        </table>
      </div>

      <PurchaseReceiptDialog open={dialogOpen} onClose={() => setDialogOpen(false)} lockSupplierId={supplier.id} />
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { NavLink } from "@/components/ui/nav-link";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { toast } from "@/components/ui/toast";
import { type ColumnDef } from "@tanstack/react-table";
import { useStore, type Supplier } from "@/lib/store";
import { supplierSchema, type SupplierFormValues } from "@/lib/schemas";
import { SortableTable } from "@/components/ui/sortable-table";

function AddSupplierDialog({ open, onClose }: { open: boolean; onClose: () => void }) {
  const addSupplier = useStore((s) => s.addSupplier);
  const { register, handleSubmit, reset, formState: { errors, isSubmitting } } = useForm<SupplierFormValues>({
    resolver: zodResolver(supplierSchema),
    defaultValues: { name: "", phone: "", address: "" },
  });
  if (!open) return null;
  const onSubmit = async (values: SupplierFormValues) => {
    try {
      await addSupplier(values);
      toast.success(`Supplier "${values.name}" added`);
      reset(); onClose();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to add supplier");
    }
  };
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 sm:p-4">
      <form onSubmit={handleSubmit(onSubmit)} className="w-full max-w-sm rounded-xl border border-[var(--surface-border)] bg-[var(--surface)] p-5 space-y-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-lg font-semibold text-[var(--foreground)]">Add Supplier</h2>
        <div className="space-y-3">
          <div>
            <label className="text-sm text-[var(--text-muted)]">Name</label>
            <input {...register("name")}
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.name && <p className="text-xs text-red-400 mt-1">{errors.name.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Phone</label>
            <input {...register("phone")} placeholder="0300-1234567"
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
            {errors.phone && <p className="text-xs text-red-400 mt-1">{errors.phone.message}</p>}
          </div>
          <div>
            <label className="text-sm text-[var(--text-muted)]">Address (optional)</label>
            <input {...register("address")}
              className="mt-1 w-full rounded-lg border border-[var(--surface-border)] bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] outline-none focus:border-[var(--surface-border-strong)]" />
          </div>
        </div>
        <div className="flex justify-end gap-2 pt-2">
          <button type="button" onClick={() => { reset(); onClose(); }} className="rounded-lg px-4 py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--surface-hover)]">Cancel</button>
          <button type="submit" disabled={isSubmitting} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity disabled:opacity-50">
            {isSubmitting ? "Saving..." : "Save"}
          </button>
        </div>
      </form>
    </div>
  );
}

export default function SuppliersPage() {
  const suppliers = useStore((s) => s.suppliers);
  const receipts = useStore((s) => s.receipts);
  const loadRawMaterialsModule = useStore((s) => s.loadRawMaterialsModule);
  const [dialogOpen, setDialogOpen] = useState(false);

  useEffect(() => {
    loadRawMaterialsModule();
  }, [loadRawMaterialsModule]);

  type Row = Supplier & { totalPurchases: number; lastPurchaseDate: string };

  const rows = useMemo<Row[]>(() => {
    return suppliers.map((sup) => {
      const supReceipts = receipts.filter((r) => r.supplierId === sup.id);
      const lastPurchaseDate = supReceipts.length > 0
        ? supReceipts.map((r) => r.purchaseDate).sort().reverse()[0]
        : "-";
      return { ...sup, totalPurchases: supReceipts.length, lastPurchaseDate };
    });
  }, [suppliers, receipts]);

  const columns = useMemo<ColumnDef<Row, unknown>[]>(() => [
    {
      accessorKey: "name", header: "Name",
      cell: ({ row }) => <NavLink href={`/suppliers/${row.original.id}`} className="text-[var(--foreground)] hover:underline">{row.original.name}</NavLink>,
    },
    { accessorKey: "phone", header: "Phone" },
    { accessorKey: "totalPurchases", header: "Total Purchases" },
    { accessorKey: "lastPurchaseDate", header: "Last Purchase Date" },
  ], []);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-xl font-semibold text-[var(--foreground)]">Suppliers</h1>
        <button onClick={() => setDialogOpen(true)} className="rounded-lg bg-neutral-900 dark:bg-neutral-50 px-4 py-2 text-sm font-medium text-neutral-50 dark:text-neutral-950 hover:opacity-90 transition-opacity">
          + Add Supplier
        </button>
      </div>
      <SortableTable data={rows} columns={columns} globalFilterPlaceholder="Search suppliers..." onRefresh={loadRawMaterialsModule} />
      <AddSupplierDialog open={dialogOpen} onClose={() => setDialogOpen(false)} />
    </div>
  );
}

@import "tailwindcss";
@custom-variant dark (&:where(.dark, .dark *));

:root {
  --background: #ffffff;
  --foreground: #171717;
  --surface: #f5f6f8;
  --surface-hover: #ebedf0;
  --surface-border: #e3e6ea;
  --surface-border-strong: #c7cbd1;
  --text-secondary: #4b5563;
  --text-muted: #6b7280;
  --text-faint: #9ca3af;
}

.dark {
  --background: #0a0a0a;
  --foreground: #f5f5f5;
  --surface: #171717;
  --surface-hover: #262626;
  --surface-border: #262626;
  --surface-border-strong: #404040;
  --text-secondary: #d4d4d4;
  --text-muted: #a3a3a3;
  --text-faint: #737373;
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: Arial, Helvetica, sans-serif;
  transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}

::view-transition-old(root),
::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
}

/* ---- Toast component design tokens (added by update-toast-design.ps1) ---- */
@theme inline {
  --color-gray-1000: var(--ds-gray-1000);
  --color-background-100: var(--ds-background-100);
  --color-contrast-fg: var(--ds-contrast-fg);
  --color-geist-background: var(--geist-background);
  --shadow-menu: var(--ds-shadow-menu);
}

:root {
  --ds-contrast-fg: #ffffff;
  --geist-background: #fff;
