  name: z.string().trim().min(2, "Name must be at least 2 characters"),
  unit: z.string().trim().min(1, "Unit is required"),
  lowStockThreshold: z.coerce.number().min(0, "Threshold cannot be negative"),
});
export type RawMaterialMasterFormValues = z.infer<typeof rawMaterialMasterSchema>;

// ---------------------------------------------------------------------------
// Multi-item Purchase Receipt (FR-5, FR-6, FR-7)
// One Supplier + one Purchase Date, one or more line items.
// ---------------------------------------------------------------------------

export const purchaseReceiptLineSchema = z.object({
  rawMaterialId: z.string().min(1, "Select a raw material"),
  qty: z.coerce.number().positive("Quantity must be greater than 0"),
  cost: z.coerce.number().positive("Cost must be greater than 0"),
});
export type PurchaseReceiptLineValues = z.infer<typeof purchaseReceiptLineSchema>;

export const purchaseReceiptSchema = z.object({
  supplierId: z.string().min(1, "Select a supplier"),
  purchaseDate: z.string().min(1, "Purchase date is required"),
  items: z.array(purchaseReceiptLineSchema).min(1, "Add at least one item"),
});
export type PurchaseReceiptFormValues = z.infer<typeof purchaseReceiptSchema>;

// ---------------------------------------------------------------------------
// Wrapper / Box - raw-material-linked production (FR-11 - FR-15)
// ---------------------------------------------------------------------------

// Used to Define a Wrapper or a Box (same shape per BRS section 6).
export const wrapperDefinitionSchema = z.object({
  name: z.string().trim().min(2, "Name must be at least 2 characters"),
  rawMaterialId: z.string().min(1, "Select the underlying raw material"),
  gramsPerUnit: z.coerce.number().positive("Grams per unit must be greater than 0"),
  lowStockThreshold: z.coerce.number().min(0, "Threshold cannot be negative"),
});
export type WrapperDefinitionFormValues = z.infer<typeof wrapperDefinitionSchema>;

export const boxDefinitionSchema = wrapperDefinitionSchema;
export type BoxDefinitionFormValues = z.infer<typeof boxDefinitionSchema>;

// Used for a Wrapper Production Run or a Box Production Run. Only the
// quantity to produce is user-entered - grams consumed are always derived,
// never user-editable (FR-14).
export const productionRunSchema = z.object({
  quantityProduced: z.coerce
    .number()
    .int("Must be a whole number")
    .positive("Must be greater than 0"),
});
export type ProductionRunFormValues = z.infer<typeof productionRunSchema>;

// ---------------------------------------------------------------------------
// Carton Configuration - now named (FR-16)
// ---------------------------------------------------------------------------

export const cartonConfigSchema = z.object({
  name: z.string().trim().min(1, "Configuration name is required"),
  wrapperId: z.string().min(1, "Select a wrapper"),
  packetsPerBox: z.coerce.number().int("Must be a whole number").positive("Must be greater than 0"),
  boxId: z.string().min(1, "Select a box"),
  boxesPerCarton: z.coerce.number().int("Must be a whole number").positive("Must be greater than 0"),
});
export type CartonConfigFormValues = z.infer<typeof cartonConfigSchema>;

// ---------------------------------------------------------------------------
// Production Batch
// ---------------------------------------------------------------------------

export const batchSchema = z.object({
  outputYieldKg: z.coerce.number().positive("Output yield must be greater than 0"),
  wastageKg: z.coerce.number().min(0, "Wastage cannot be negative"),
});
export type BatchFormValues = z.infer<typeof batchSchema>;

export const overheadSchema = z.object({
  electricity: z.coerce.number().min(0, "Cannot be negative"),
  gas: z.coerce.number().min(0, "Cannot be negative"),
  rent: z.coerce.number().min(0, "Cannot be negative"),
});
export type OverheadFormValues = z.infer<typeof overheadSchema>;

// ---------------------------------------------------------------------------
// Batch Expenses & Monthly Overhead (0007)
// ---------------------------------------------------------------------------

export const batchExpenseSchema = z.object({
  name: z.string().trim().min(1, "Expense name is required"),
  amount: z.coerce.number().min(0, "Cannot be negative"),
});
export type BatchExpenseFormValues = z.infer<typeof batchExpenseSchema>;

export const monthlyExpenseSchema = z.object({
  month: z.string().min(1, "Month is required"),
  name: z.string().trim().min(1, "Expense name is required"),
  amount: z.coerce.number().min(0, "Cannot be negative"),
});
export type MonthlyExpenseFormValues = z.infer<typeof monthlyExpenseSchema>;

// ---------------------------------------------------------------------------
// Packing Run - carton count only, everything else derived (FR-23 - FR-29)
// ---------------------------------------------------------------------------

export const packingRunSchema = z.object({
  batchId: z.string().min(1, "Select a batch"),
  configId: z.string().min(1, "Select a carton configuration"),
  cartonsProduced: z.coerce.number().int("Must be a whole number").positive("Must be greater than 0"),
});
export type PackingRunFormValues = z.infer<typeof packingRunSchema>;

// ---------------------------------------------------------------------------
// Customers & Invoicing
// ---------------------------------------------------------------------------

export const customerSchema = z.object({
  name: z.string().trim().min(2, "Name must be at least 2 characters"),
  phone: z
    .string()
    .trim()
    .min(7, "Enter a valid phone number")
    .regex(/^[0-9+\-()\s]+$/, "Phone can only contain digits, spaces, + - ( )"),
  openingBalance: z.coerce.number(),
});
export type CustomerFormValues = z.infer<typeof customerSchema>;

export const invoiceHeaderSchema = z.object({
  customerId: z.string().min(1, "Select a customer"),
  margin: z.coerce.number().min(0, "Margin cannot be negative"),
});
export type InvoiceHeaderFormValues = z.infer<typeof invoiceHeaderSchema>;

// ---------------------------------------------------------------------------
// Customer Ledger - Record Payment / Adjustment, explicit direction (FR-42)
// ---------------------------------------------------------------------------

export const paymentSchema = z.object({
  customerId: z.string().min(1, "Select a customer"),
  amount: z.coerce.number().positive("Amount must be greater than 0"),
  direction: z.enum(["received", "given"], {
    required_error: "Select a direction",
  }),
  note: z.string().trim().optional(),
});
export type PaymentFormValues = z.infer<typeof paymentSchema>;

"use client";

import { createContext, useContext, useEffect, useState, type ReactNode } from "react";
import { usePathname } from "next/navigation";

type SidebarContextValue = {
  isOpen: boolean;
  open: () => void;
  close: () => void;
  toggle: () => void;
};

const SidebarContext = createContext<SidebarContextValue | null>(null);

export function SidebarProvider({ children }: { children: ReactNode }) {
  const [isOpen, setIsOpen] = useState(false);
  const pathname = usePathname();

  // Auto-close the mobile drawer whenever the route changes.
  useEffect(() => {
    setIsOpen(false);
  }, [pathname]);

  return (
    <SidebarContext.Provider
      value={{
        isOpen,
        open: () => setIsOpen(true),
        close: () => setIsOpen(false),
        toggle: () => setIsOpen((v) => !v),
      }}
    >
      {children}
    </SidebarContext.Provider>
  );
}

export function useSidebar() {
  const ctx = useContext(SidebarContext);
  if (!ctx) throw new Error("useSidebar must be used within SidebarProvider");
  return ctx;
}

"use client";

import { create } from "zustand";
import { createClient } from "@/lib/supabase/client";

const supabase = createClient();

// =============================================================================
// Row mappers (snake_case DB rows -> camelCase domain types)
// =============================================================================

function mapSupplierRow(row: Record<string, any>): Supplier {
  return { id: row.id, name: row.name, phone: row.phone, address: row.address ?? undefined };
}
function mapRawMaterialRow(row: Record<string, any>): RawMaterial {
  return {
    id: row.id,
    name: row.name,
    unit: row.unit,
    quantityInStock: Number(row.quantity_in_stock),
    avgUnitCost: Number(row.avg_unit_cost),
    lowStockThreshold: Number(row.low_stock_threshold),
  };
}
function mapReceiptRow(row: Record<string, any>): PurchaseReceipt {
  return { id: row.id, supplierId: row.supplier_id, purchaseDate: row.purchase_date };
}
function mapReceiptLineRow(row: Record<string, any>): PurchaseReceiptLine {
  return { id: row.id, receiptId: row.receipt_id, rawMaterialId: row.raw_material_id, qty: Number(row.qty), cost: Number(row.cost) };
}
function mapWrapperRow(row: Record<string, any>): Wrapper {
  return {
    id: row.id,
    name: row.name,
    rawMaterialId: row.raw_material_id,
    gramsPerUnit: Number(row.grams_per_unit),
    stockQty: Number(row.stock_qty),
    lowStockThreshold: Number(row.low_stock_threshold),
  };
}
function mapBoxRow(row: Record<string, any>): Box {
  return {
    id: row.id,
    name: row.name,
    rawMaterialId: row.raw_material_id,
    gramsPerUnit: Number(row.grams_per_unit),
    stockQty: Number(row.stock_qty),
    lowStockThreshold: Number(row.low_stock_threshold),
  };
}
function mapWrapperRunRow(row: Record<string, any>): WrapperProductionRun {
  return {
    id: row.id,
    wrapperId: row.wrapper_id,
    quantityProduced: Number(row.quantity_produced),
    gramsConsumed: Number(row.grams_consumed),
    date: row.run_date,
  };
}
function mapBoxRunRow(row: Record<string, any>): BoxProductionRun {
  return {
    id: row.id,
    boxId: row.box_id,
    quantityProduced: Number(row.quantity_produced),
    gramsConsumed: Number(row.grams_consumed),
    date: row.run_date,
  };
}
function mapCartonConfigRow(row: Record<string, any>): CartonConfiguration {
  return {
    id: row.id,
    name: row.name,
    wrapperId: row.wrapper_id,
    packetsPerBox: Number(row.packets_per_box),
    boxId: row.box_id,
    boxesPerCarton: Number(row.boxes_per_carton),
    usedInPackingRun: Boolean(row.used_in_packing_run),
  };
}
function mapBatchRow(row: Record<string, any>): ProductionBatch {
  return {
    id: row.id,
    batchDate: row.batch_date,
    outputYieldKg: Number(row.output_yield_kg),
    wastageKg: Number(row.wastage_kg),
    leftoverQtyKg: Number(row.leftover_qty_kg),
    bulkCostPerKg: Number(row.bulk_cost_per_kg),
    overheadTotal: Number(row.overhead_total),
    status: row.status,
    leftoverSourceBatchId: row.leftover_source_batch_id ?? undefined,
    leftoverKgConsumed: row.leftover_kg_consumed != null ? Number(row.leftover_kg_consumed) : undefined,
  };
}
function mapFinishedCartonRow(row: Record<string, any>): FinishedCarton {
  return {
    id: row.id,
    name: row.name,
    sourceBatchId: row.source_batch_id,
    configId: row.config_id,
    cartonsProduced: Number(row.cartons_produced),
    packetsPerCarton: Number(row.packets_per_carton),
    costPerCarton: Number(row.cost_per_carton),
    costPerBox: Number(row.cost_per_box),
    costPerPacket: Number(row.cost_per_packet),
    stockQty: Number(row.stock_qty),
  };
}
function mapCustomerRow(row: Record<string, any>): Customer {
  return { id: row.id, name: row.name, phone: row.phone, currentBalance: Number(row.current_balance) };
}
function mapCustomerItemPriceRow(row: Record<string, any>): CustomerItemPrice {
  return {
    customerId: row.customer_id,
    itemId: row.item_id,
    lastSoldPrice: Number(row.last_sold_price),
    lastSoldDate: row.last_sold_date,
  };
}
function mapInvoiceRow(row: Record<string, any>, customerName: string, items: InvoiceLineRecord[]): Invoice {
  return {
    id: row.invoice_number ?? row.id,
    customerId: row.customer_id,
    customerName,
    invoiceDate: row.invoice_date,
    totalAmount: Number(row.total_amount),
    items,
  };
}
function mapInvoiceItemRow(row: Record<string, any>): InvoiceLineRecord {
  return {
    itemId: row.finished_carton_id,
    itemName: row.item_name,
    qty: Number(row.qty),
    unitPrice: Number(row.unit_price),
    subtotal: Number(row.subtotal),
    priceSourceNote: row.price_source_note ?? undefined,
  };
}
function mapLedgerRow(row: Record<string, any>): LedgerEntry {
  return {
    id: row.id,
    customerId: row.customer_id,
    type: row.type,
    direction: row.direction,
    amount: Number(row.amount),
    runningBalance: Number(row.running_balance),
    date: row.entry_date,
    note: row.note ?? undefined,
  };
}
function mapPaymentRow(row: Record<string, any>, customerName: string): Payment {
  return {
    id: row.id,
    customerId: row.customer_id,
    customerName,
    amount: Number(row.amount),
    direction: row.direction,
    note: row.note ?? "",
    paidAt: row.paid_at,
  };
}
function mapSettingsRow(row: Record<string, any>): AppSettings {
  return {
    businessName: row.business_name,
    address: row.address,
    invoiceFooterText: row.invoice_footer_text ?? "",
    defaultProfitMarginPercent: Number(row.default_profit_margin_percent),
    lowStockThresholdDefault: Number(row.low_stock_threshold_default),
    overheadAllocationMethod: (row.overhead_allocation_method ?? "equal") as "equal" | "proportional_kg",
  };
}

// =============================================================================
// Types (BRS v1.2 / Frontend Spec v2.2 domain model)
// =============================================================================

export type Supplier = { id: string; name: string; phone: string; address?: string };

export type RawMaterial = {
  id: string;
  name: string;
  unit: string;
  quantityInStock: number;
  avgUnitCost: number;
  lowStockThreshold: number;
};

export type PurchaseReceipt = { id: string; supplierId: string; purchaseDate: string };

export type PurchaseReceiptLine = { id: string; receiptId: string; rawMaterialId: string; qty: number; cost: number };

export type Wrapper = {
  id: string;
  name: string;
  rawMaterialId: string;
  gramsPerUnit: number;
  stockQty: number;
  lowStockThreshold: number;
};

export type Box = {
  id: string;
  name: string;
  rawMaterialId: string;
  gramsPerUnit: number;
  stockQty: number;
  lowStockThreshold: number;
};

export type WrapperProductionRun = { id: string; wrapperId: string; quantityProduced: number; gramsConsumed: number; date: string };

export type BoxProductionRun = { id: string; boxId: string; quantityProduced: number; gramsConsumed: number; date: string };

export type CartonConfiguration = {
  id: string;
  name: string;
  wrapperId: string;
  packetsPerBox: number;
  boxId: string;
  boxesPerCarton: number;
  usedInPackingRun: boolean;
};

export type ProductionBatch = {
  id: string;
  batchDate: string;
  outputYieldKg: number;
  wastageKg: number;
  leftoverQtyKg: number;
  bulkCostPerKg: number;
  overheadTotal: number;
  status: "in_progress" | "completed";
  leftoverSourceBatchId?: string;
  leftoverKgConsumed?: number;
};

export type FinishedCarton = {
  id: string;
  name: string;
  sourceBatchId: string;
  configId: string;
  cartonsProduced: number;
  packetsPerCarton: number;
  costPerCarton: number;
  costPerBox: number;
  costPerPacket: number;
  stockQty: number;
};

export type Customer = { id: string; name: string; phone: string; currentBalance: number };

export type CustomerItemPrice = { customerId: string; itemId: string; lastSoldPrice: number; lastSoldDate: string };

export type InvoiceLineRecord = {
  itemId: string;
  itemName: string;
  qty: number;
  unitPrice: number;
  subtotal: number;
  priceSourceNote?: string;
};

export type Invoice = {
  id: string;
  customerId: string;
  customerName: string;
  invoiceDate: string;
